mapper.select:


    systemLogLogin.deleted_flag = 'N'
    and systemLogLogin.remark = #{remark}
    and systemLogLogin.login_name like concat('%',
        #{loginName}, '%')

    and systemLogLogin.nick_name like concat('%', #{nickName},
        '%')

    and systemLogLogin.login_ip = #{loginIp}
    and systemLogLogin.login_location =
        #{loginLocation}

    and systemLogLogin.browser = #{browser}
    and systemLogLogin.os = #{os}
    and systemLogLogin.platform = #{platform}
    and systemLogLogin.message like concat('%', #{message}, '%')

    and systemLogLogin.status = #{status}
    and systemLogLogin.department_id = #{departmentId}

    and systemLogLogin.organization_id =
        #{organizationId}


        and systemLogLogin.created_time between #{parameters.beginDate} and  #{parameters.endDate}


        and

            (
            systemLogLogin.remark like concat('%', #{item}, '%')
            or systemLogLogin.login_name like concat('%', #{item}, '%')
            or  systemLogLogin.login_location like concat('%', #{item}, '%')
            or systemLogLogin.message like concat('%', #{item}, '%')
            or systemLogLogin.os like concat('%', #{item}, '%')
            or systemLogLogin.browser like concat('%', #{item}, '%')
            )



order by systemLogLogin.created_time desc
